export interface Restriction {
  id: string;
  /** e.g. RS-261002-0019 */
  ref: string;
  sellerId: string;
  state: "pending_approval" | "active" | "lifted" | "expired" | "cancelled";
  /** Short label, e.g. New listings in Cameras paused */
  title: string;
  reasonCode: "performance" | "policy_violation" | "brand_claim" | "counterfeit_risk" | "fraud_risk" | "unresolved_cases" | "verification_lapsed" | "approval_condition" | "other";
  /** Shown to the seller: facts and the rule */
  reason: string;
  ruleRef?: string | null;
  /** What the restriction stops. new_listings/new_offers: no new offers; sales: in-scope offers become ineligible; product_submissions: no new catalog submissions; offer_reactivation: paused or ineligible offers cannot be reactivated */
  affectedActivities: ("new_listings" | "product_submissions" | "new_offers" | "offer_reactivation" | "sales" | "advertising" | "promotions" | "payout_schedule")[];
  /** Empty lists mean the whole account */
  scope: RestrictionScope;
  affectedSummary: string;
  /** e.g. existing orders, dispatch and shipping; returns, refunds and cases; messages; payouts */
  stillWorks: string[];
  toResolve: string;
  appealRoute: AppealRoute;
  reviewDate: string;
  startedAt?: string | null;
  endsAt?: string | null;
  setBy: common.Actor;
  recommendedBy?: common.Actor | null;
  trustReportId?: string | null;
  trustEnforcementId?: string | null;
  approval?: common.ApprovalInfo | null;
  appeals: Appeal[];
  resolutionEvidence: common.MediaRef[];
  liftedAt?: string | null;
  liftReason?: string | null;
}

